155	#[derive(Debug, PartialEq, Eq, Clone)]
156	enum ParseState<'a> {
157	    /// Parsing a value done, there is no state to record.
158	    ValueDone,
159	
160	    /// Parsing a positional argument after `--`. `Pos(pos_index`, `takes_num_args`)
161	    Pos((usize, usize)),
162	
163	    /// Parsing a optional flag argument
164	    Opt((&'a clap::Arg, usize)),
165	}
