167	fn complete_arg(
168	    arg: &clap_lex::ParsedArg<'_>,
169	    cmd: &clap::Command,
170	    current_dir: Option<&std::path::Path>,
171	    pos_index: usize,
172	    is_escaped: bool,
173	    state: ParseState<'_>,
174	) -> Result<Vec<CompletionCandidate>, std::io::Error> {
175	    debug!(
176	        "complete_arg: arg={:?}, cmd={:?}, current_dir={:?}, pos_index={:?}, state={:?}",
177	        arg,
178	        cmd.get_name(),
179	        current_dir,
180	        pos_index,
181	        state
182	    );
183	    let mut completions = Vec::<CompletionCandidate>::new();
184	
185	    match state {
186	        ParseState::ValueDone => {
187	            // After `--`, subcommands are no longer recognized; every token is
188	            // parsed as a positional value.
189	            if !is_escaped {
190	                if let Ok(value) = arg.to_value() {
191	                    completions.extend(complete_subcommand(value, cmd));
192	                }
193	            }
194	
195	            if let Some(positional) = cmd
196	                .get_positionals()
197	                .find(|p| p.get_index() == Some(pos_index))
198	            {
199	                completions.extend(complete_arg_value(
200	                    arg.to_value(),
201	                    positional,
202	                    current_dir,
203	                    0,
204	                ));
205	            }
206	            if !is_escaped {
207	                completions.extend(complete_option(arg, cmd, current_dir));
208	            }
209	        }
210	        ParseState::Pos((_, num_arg)) => {
211	            if let Some(positional) = cmd
212	                .get_positionals()
213	                .find(|p| p.get_index() == Some(pos_index))
214	            {
215	                completions.extend(complete_arg_value(
216	                    arg.to_value(),
217	                    positional,
218	                    current_dir,
219	                    num_arg.saturating_sub(1),
220	                ));
221	                if !is_escaped
222	                    && positional
223	                        .get_num_args()
224	                        .is_some_and(|num_args| num_arg >= num_args.min_values())
225	                {
226	                    completions.extend(complete_option(arg, cmd, current_dir));
227	                }
228	            }
229	        }
230	        ParseState::Opt((opt, count)) => {
231	            completions.extend(complete_arg_value(
232	                arg.to_value(),
233	                opt,
234	                current_dir,
235	                count.saturating_sub(1),
236	            ));
237	            let min = opt.get_num_args().map(|r| r.min_values()).unwrap_or(0);
238	            if count > min {
239	                // Also complete this raw_arg as a positional argument, flags, options and subcommand.
240	                completions.extend(complete_arg(
241	                    arg,
242	                    cmd,
243	                    current_dir,
244	                    pos_index,
245	                    is_escaped,
246	                    ParseState::ValueDone,
247	                )?);
248	            }
249	        }
250	    }
251	    if completions.iter().any(|a| !a.is_hide_set()) {
252	        completions.retain(|a| !a.is_hide_set());
253	    }
254	    let mut seen_ids = std::collections::HashSet::new();
255	    let mut seen_values = std::collections::HashSet::new();
256	    completions.retain(move |a| {
257	        if let Some(id) = a.get_id().cloned() {
258	            seen_ids.insert(id)
259	        } else {
260	            // Candidates without an id are deduplicated by value, keeping the
261	            // first occurrence
262	            seen_values.insert(a.get_value().to_owned())
263	        }
264	    });
265	
266	    let mut tags = Vec::new();
267	    for candidate in &completions {
268	        let tag = candidate.get_tag().cloned();
269	        if !tags.contains(&tag) {
270	            tags.push(tag);
271	        }
272	    }
273	    completions.sort_by_key(|c| {
274	        (
275	            tags.iter().position(|t| c.get_tag() == t.as_ref()),
276	            c.get_display_order(),
277	        )
278	    });
279	
280	    Ok(completions)
281	}
