482	fn complete_value_candidates(
483	    value: &OsStr,
484	    completer: &dyn ValueCandidates,
485	) -> Vec<CompletionCandidate> {
486	    debug!("complete_value_candidates: value={value:?}");
487	
488	    let mut values = completer.candidates();
489	    values.retain(|comp| comp.get_value().starts_with(&value.to_string_lossy()));
490	    values
491	}
492	
493	fn complete_candidates_str(
494	    value: &str,
495	    mut values: Vec<CompletionCandidate>,
496	) -> Vec<CompletionCandidate> {
497	    debug!("complete_candidates_str: value={value:?}");
498	
499	    values.retain(|comp| comp.get_value().starts_with(value));
500	    values
501	}
502	
503	fn complete_value_candidates_str(
504	    value: &str,
505	    completer: &dyn ValueCandidates,
506	) -> Vec<CompletionCandidate> {
507	    debug!("complete_value_candidates_str: value={value:?}");
508	
509	    complete_candidates_str(value, completer.candidates())
510	}
