606	/// Get the possible values for completion
607	fn possible_values(
608	    a: &clap::Arg,
609	) -> Option<Box<dyn Iterator<Item = clap::builder::PossibleValue> + '_>> {
610	    if !a.get_num_args().expect("built").takes_values() {
611	        None
612	    } else {
613	        a.get_value_parser().possible_values()
614	    }
615	}
616	
617	/// Gets subcommands of [`clap::Command`] in the form of `("name", "bin_name")`.
618	///
619	/// Subcommand `rustup toolchain install` would be converted to
620	/// `("install", "rustup toolchain install")`.
621	fn subcommands(p: &clap::Command) -> Vec<CompletionCandidate> {
622	    debug!("subcommands: name={}", p.get_name());
623	    debug!("subcommands: Has subcommands...{:?}", p.has_subcommands());
624	    p.get_subcommands()
625	        .flat_map(|sc| {
626	            sc.get_name_and_visible_aliases()
627	                .into_iter()
628	                .map(|s| populate_command_candidate(CompletionCandidate::new(s.to_owned()), p, sc))
629	                .chain(sc.get_aliases().map(|s| {
630	                    populate_command_candidate(CompletionCandidate::new(s.to_owned()), p, sc)
631	                        .hide(true)
632	                }))
633	        })
634	        .collect()
635	}
636	
637	fn populate_command_candidate(
638	    candidate: CompletionCandidate,
639	    cmd: &clap::Command,
640	    subcommand: &clap::Command,
641	) -> CompletionCandidate {
642	    candidate
643	        .help(subcommand.get_about().cloned())
644	        .id(Some(format!("command::{}", subcommand.get_name())))
645	        .tag(Some(
646	            cmd.get_subcommand_help_heading()
647	                .unwrap_or("Commands")
648	                .to_owned()
649	                .into(),
650	        ))
651	        .display_order(Some(subcommand.get_display_order()))
652	        .hide(subcommand.is_hide_set())
653	}
654	
655	/// Parse the short flags and find the first `takes_values` option.
656	fn parse_shortflags<'c, 's>(
657	    cmd: &'c clap::Command,
658	    mut short: clap_lex::ShortFlags<'s>,
659	) -> (String, Option<&'c clap::Arg>, clap_lex::ShortFlags<'s>) {
660	    let takes_value_opt;
661	    let mut leading_flags = String::new();
662	    // Find the first takes_values option.
663	    loop {
664	        match short.next_flag() {
665	            Some(Ok(opt)) => {
666	                leading_flags.push(opt);
667	                let opt = cmd.get_arguments().find(|a| {
668	                    let shorts = a.get_short_and_visible_aliases();
669	                    let is_find = shorts.map(|v| {
670	                        let mut iter = v.into_iter();
671	                        let c = iter.find(|c| *c == opt);
672	                        c.is_some()
673	                    });
674	                    is_find.unwrap_or(false)
675	                });
676	                if opt
677	                    .map(|o| o.get_num_args().expect("built").takes_values())
678	                    .unwrap_or(false)
679	                {
680	                    takes_value_opt = opt;
681	                    break;
682	                }
683	            }
684	            Some(Err(_)) | None => {
685	                takes_value_opt = None;
686	                break;
687	            }
688	        }
689	    }
690	
691	    (leading_flags, takes_value_opt, short)
692	}
693	
694	/// Parse the positional arguments. Return the new state and the new positional index.
695	fn parse_positional<'a>(
696	    cmd: &clap::Command,
697	    pos_index: usize,
698	    is_escaped: bool,
699	    state: ParseState<'a>,
700	) -> (ParseState<'a>, usize) {
701	    let pos_arg = cmd
702	        .get_positionals()
703	        .find(|p| p.get_index() == Some(pos_index));
704	    let num_args = pos_arg
705	        .and_then(|a| a.get_num_args().map(|r| r.max_values()))
706	        .unwrap_or(1);
707	
708	    let update_state_with_new_positional = |pos_index| -> (ParseState<'a>, usize) {
709	        if num_args > 1 {
710	            (ParseState::Pos((pos_index, 1)), pos_index)
711	        } else {
712	            if is_escaped {
713	                (ParseState::Pos((pos_index, 1)), pos_index + 1)
714	            } else {
715	                (ParseState::ValueDone, pos_index + 1)
716	            }
717	        }
718	    };
719	    match state {
720	        ParseState::ValueDone => {
721	            update_state_with_new_positional(pos_index)
722	        },
723	        ParseState::Pos((prev_pos_index, num_arg)) => {
724	            if prev_pos_index == pos_index {
725	                if num_arg + 1 < num_args {
726	                    (ParseState::Pos((pos_index, num_arg + 1)), pos_index)
727	                } else {
728	                    if is_escaped {
729	                        (ParseState::Pos((pos_index, 1)), pos_index + 1)
730	                    } else {
731	                        (ParseState::ValueDone, pos_index + 1)
732	                    }
733	                }
734	            } else {
735	                update_state_with_new_positional(pos_index)
736	            }
737	        }
738	        ParseState::Opt(..) => unreachable!(
739	            "This branch won't be hit,
740	            because ParseState::Opt should not be seen as a positional argument and passed to this function."
741	        ),
742	    }
743	}
744	
745	/// Parse optional flag argument. Return new state
746	fn parse_opt_value(opt: &clap::Arg, count: usize) -> ParseState<'_> {
747	    let range = opt.get_num_args().expect("built");
748	    let max = range.max_values();
749	    if count < max {
750	        ParseState::Opt((opt, count + 1))
751	    } else {
752	        ParseState::ValueDone
753	    }
754	}
755	
756	fn pos_allows_hyphen(cmd: &clap::Command, pos_index: usize) -> bool {
757	    cmd.get_positionals()
758	        .find(|a| a.get_index() == Some(pos_index))
759	        .map(|p| p.is_allow_hyphen_values_set())
760	        .unwrap_or(false)
761	}
762	
763	fn opt_allows_hyphen(state: &ParseState<'_>, arg: &clap_lex::ParsedArg<'_>) -> bool {
764	    let val = arg.to_value_os();
765	    if val.starts_with("-") {
766	        if let ParseState::Opt((opt, _)) = state {
767	            return opt.is_allow_hyphen_values_set();
768	        }
769	    }
770	
771	    false
772	}
