use std::ffi::OsStr;
use std::ffi::OsString;

use clap::builder::StyledStr;

/// A shell-agnostic completion candidate
#[derive(Default, Debug, PartialEq, Eq, PartialOrd, Ord)]
pub struct CompletionCandidate {
    value: OsString,
    help: Option<StyledStr>,
    id: Option<String>,
    tag: Option<StyledStr>,
    display_order: Option<usize>,
    hidden: bool,
}

impl CompletionCandidate {
    /// Create a new completion candidate
    pub fn new(value: impl Into<OsString>) -> Self {
        let value = value.into();
        Self {
            value,
            ..Default::default()
        }
    }

    /// Set the help message of the completion candidate
    pub fn help(mut self, help: Option<StyledStr>) -> Self {
        self.help = help;
        self
    }

    /// Only first for a given Id is shown
    ///
    /// To reduce the risk of conflicts, this should likely contain a namespace.
    pub fn id(mut self, id: Option<String>) -> Self {
        self.id = id;
        self
    }

    /// Group candidates by tag
    ///
    /// Future: these may become user-visible
    pub fn tag(mut self, tag: Option<StyledStr>) -> Self {
        self.tag = tag;
        self
    }

    /// Sort weight within a [`CompletionCandidate::tag`]
    pub fn display_order(mut self, order: Option<usize>) -> Self {
        self.display_order = order;
        self
    }

    /// Set the visibility of the completion candidate
    ///
    /// Only shown when there is no visible candidate for completing the current argument.
    pub fn hide(mut self, hidden: bool) -> Self {
        self.hidden = hidden;
        self
    }

    /// Add a prefix to the value of completion candidate
    ///
    /// This is generally used for post-process by [`complete`][crate::engine::complete()] for
    /// things like prepending flags, merging delimiter-separated values, etc.
    pub fn add_prefix(mut self, prefix: impl Into<OsString>) -> Self {
        let suffix = self.value;
        let mut value = prefix.into();
        value.push(&suffix);
        self.value = value;
        self
    }
}

/// Reflection API
impl CompletionCandidate {
    /// Get the literal value being proposed for completion
    pub fn get_value(&self) -> &OsStr {
        &self.value
    }

    /// Get the help message of the completion candidate
    pub fn get_help(&self) -> Option<&StyledStr> {
        self.help.as_ref()
    }

    /// Get the id used for de-duplicating
    pub fn get_id(&self) -> Option<&String> {
        self.id.as_ref()
    }

    /// Get the grouping tag
    pub fn get_tag(&self) -> Option<&StyledStr> {
        self.tag.as_ref()
    }

    /// Get the grouping tag
    pub fn get_display_order(&self) -> Option<usize> {
        self.display_order
    }

    /// Get the visibility of the completion candidate
    pub fn is_hide_set(&self) -> bool {
        self.hidden
    }
}

impl<S: Into<OsString>> From<S> for CompletionCandidate {
    fn from(s: S) -> Self {
        Self::new(s.into())
    }
}

fn sort_and_filter() {
    let mut cmd = Command::new("exhaustive")
        .args([
            clap::Arg::new("required-flag")
                .long("required-flag")
                .visible_alias("required-flag2")
                .short('r')
                .required(true),
            clap::Arg::new("optional-flag")
                .long("optional-flag")
                .visible_alias("2optional-flag")
                .short('o'),
            clap::Arg::new("long-flag").long("long-flag"),
            clap::Arg::new("short-flag").short('s'),
            clap::Arg::new("positional").value_parser(["pos-a", "pos-b", "pos-c"]),
        ])
        .subcommands([Command::new("sub")]);

    assert_data_eq!(
        complete!(cmd, " [TAB]"),
        snapbox::str![[r#"
sub
help	Print this message or the help of the given subcommand(s)
pos-a
pos-b
pos-c
--required-flag
--optional-flag
--long-flag
-s
--help	Print help
"#]]
    );
    assert_data_eq!(
        complete!(cmd, "-[TAB]"),
        snapbox::str![[r#"
-r	--required-flag
-o	--optional-flag
--long-flag
-s
-h	Print help
"#]]
    );
    assert_data_eq!(
        complete!(cmd, "--[TAB]"),
        snapbox::str![[r#"
--required-flag
--optional-flag
--long-flag
--help	Print help
"#]]
    );
}

fn inspect_command() -> Command {
    fn name_candidates() -> Vec<CompletionCandidate> {
        vec![
            CompletionCandidate::new("alice"),
            CompletionCandidate::new("alina"),
            // Repeated on purpose: only the first occurrence may be completed
            CompletionCandidate::new("alina"),
            CompletionCandidate::new("bob"),
        ]
    }

    Command::new("inspect")
        .alias("i")
        .arg(
            clap::Arg::new("name")
                .long("name")
                .add(ArgValueCandidates::new(name_candidates)),
        )
        .arg(
            clap::Arg::new("format")
                .long("format")
                .value_parser(["json", "yaml"]),
        )
        .arg(clap::Arg::new("query").value_parser(["all", "changed"]))
        .arg(
            clap::Arg::new("internal")
                .long("internal")
                .action(clap::ArgAction::SetTrue)
                .hide(true),
        )
        .subcommand(
            Command::new("debug")
                .hide(true)
                .arg(clap::Arg::new("level").value_parser(["on", "off"])),
        )
}

/// The full command tree: direct applets `busybox`, `inspect` and `status`,
/// with `busybox` also dispatching to `inspect`.
fn custom_candidates_command() -> Command {
    Command::new("tool")
        .subcommand(Command::new("busybox").subcommand(inspect_command()))
        .subcommand(inspect_command())
        .subcommand(Command::new("status"))
}

/// Call `clap_complete::engine::complete` with a full argv (including argv0),
/// the cursor sitting on the last token, and return the candidate values.
fn complete_argv(cmd: &mut Command, argv: &[&str]) -> Vec<String> {
    let arg_index = argv.len() - 1;
    let args = argv.iter().map(std::ffi::OsString::from).collect();
    clap_complete::engine::complete(cmd, args, arg_index, None)
        .unwrap()
        .into_iter()
        .map(|candidate| candidate.get_value().to_string_lossy().into_owned())
        .collect()
}

#[test]
fn suggest_custom_arg_value_candidates_via_alias() {
    let mut cmd = custom_candidates_command();

    let expected = vec!["alice", "alina", "bob"];
    assert_eq!(
        complete_argv(&mut cmd, &["tool", "inspect", "--name", ""]),
        expected

